// ClickUp status (lower-case) -> funnel stage. Terminal stages set leads.outcome.
const STAGE_BY_STATUS = {
  'qualified': 'qualified',
  'discovery set': 'discovery_set',
  'discovery done': 'discovery_showed',
  'ambition interview': 'ambition_interview',
  'architect session': 'architect_session',
  'trial': 'trial',
  'enrolled': 'full',
  'dropped': 'dropped',
};
const SOURCES = ['meta', 'organic', 'referral', 'workshop'];
const trigger = $('ClickUp: lead status changed').first().json;
const change = (trigger.history_items || []).find(h => h.field === 'status') || {};
const eventAt = new Date(Number(change.date || Date.now())).toISOString();
const ms = v => (v ? new Date(Number(v)).toISOString() : null);

return $input.all().map(({ json: task }) => {
  const cf = name => (task.custom_fields || []).find(f => f.name.toLowerCase() === name);
  const value = name => cf(name)?.value ?? null;
  const option = name => {
    const f = cf(name);
    if (!f || f.value == null) return null;
    const o = (f.type_config?.options || []).find(x => x.orderindex === f.value || x.id === f.value);
    return o ? o.name.toLowerCase() : null;
  };
  const source = option('source');
  return {
    json: {
      clickup_task_id: task.id,
      created_at: ms(task.date_created),
      source: SOURCES.includes(source) ? source : (value('meta ad id') ? 'meta' : 'organic'),
      campaign_id: value('meta campaign id'),
      ad_id: value('meta ad id'),
      parent_name: value('parent name') || task.name,
      parent_phone: value('parent phone'),
      teen_grade: value('grade') ? Number(value('grade')) : null,
      discovery_call_at: ms(value('discovery call at')) || ms(task.due_date),
      drop_reason: option('drop reason'),
      stage: STAGE_BY_STATUS[task.status.status.toLowerCase()] || null,
      event_at: eventAt,
    },
  };
});

const out = [];
for (const { json: lead } of $input.all()) {
  const callAt = new Date(lead.discovery_call_at).getTime();
  for (const [slot, hours] of [['T-24h', 24], ['T-1h', 1]]) {
    const at = callAt - hours * 3600 * 1000;
    if (at <= Date.now()) continue; // call booked too close for this reminder
    out.push({
      json: {
        lead_id: lead.lead_id,
        phone: lead.parent_phone,
        parent_name: lead.parent_name,
        slot,
        scheduled_at: new Date(at).toISOString(),
        call_at: new Date(callAt).toISOString(),
        idempotency_key: [lead.clickup_task_id, callAt, slot].join(':'),
      },
    });
  }
}
return out;
